package inject_test

import (
	"os"
	"path/filepath"
	"testing"

	. "github.com/go-risk-it/go-risk-it/cmd/archdiagram/inject"
)

func TestInjectBetweenMarkers(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		content     string
		markerName  string
		replacement string
		want        string
		wantErr     string
	}{
		{
			name: "basic replacement",
			content: `before
<!-- GEN:TEST_START -->
old content
<!-- GEN:TEST_END -->
after`,
			markerName:  "TEST",
			replacement: "new content",
			want: `before
<!-- GEN:TEST_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
new content
<!-- GEN:TEST_END -->
after`,
		},
		{
			name: "multiline replacement",
			content: `# Title
<!-- GEN:BLOCK_START -->
old line 1
old line 2
<!-- GEN:BLOCK_END -->
footer`,
			markerName:  "BLOCK",
			replacement: "line A\nline B\nline C",
			want: `# Title
<!-- GEN:BLOCK_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
line A
line B
line C
<!-- GEN:BLOCK_END -->
footer`,
		},
		{
			name: "empty replacement",
			content: `<!-- GEN:EMPTY_START -->
old stuff
<!-- GEN:EMPTY_END -->`,
			markerName:  "EMPTY",
			replacement: "",
			want: `<!-- GEN:EMPTY_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
<!-- GEN:EMPTY_END -->`,
		},
		{
			name: "replacement with trailing newlines stripped",
			content: `<!-- GEN:TRAIL_START -->
old
<!-- GEN:TRAIL_END -->`,
			markerName:  "TRAIL",
			replacement: "new content\n\n\n",
			want: `<!-- GEN:TRAIL_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
new content
<!-- GEN:TRAIL_END -->`,
		},
		{
			name: "preserves content before and after",
			content: `line 1
line 2
<!-- GEN:MID_START -->
old
<!-- GEN:MID_END -->
line 3
line 4`,
			markerName:  "MID",
			replacement: "replaced",
			want: `line 1
line 2
<!-- GEN:MID_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
replaced
<!-- GEN:MID_END -->
line 3
line 4`,
		},
		{
			name:       "missing start marker",
			content:    `<!-- GEN:TEST_END -->`,
			markerName: "TEST",
			wantErr:    `start marker "<!-- GEN:TEST_START -->" not found`,
		},
		{
			name:       "missing end marker",
			content:    `<!-- GEN:TEST_START -->`,
			markerName: "TEST",
			wantErr:    `end marker "<!-- GEN:TEST_END -->" not found`,
		},
		{
			name: "end before start",
			content: `<!-- GEN:TEST_END -->
<!-- GEN:TEST_START -->`,
			markerName: "TEST",
			wantErr:    "end marker appears at position 0, before or at start marker position",
		},
		{
			name:       "empty marker name",
			content:    "anything",
			markerName: "",
			wantErr:    "marker name must not be empty",
		},
	}

	for _, testCase := range tests {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()

			got, err := InjectBetweenMarkers(
				testCase.content,
				testCase.markerName,
				testCase.replacement,
			)

			if testCase.wantErr != "" {
				if err == nil {
					t.Fatalf("expected error containing %q, got nil",
						testCase.wantErr)
				}

				if !contains(err.Error(), testCase.wantErr) {
					t.Fatalf("error = %q, want containing %q",
						err.Error(), testCase.wantErr)
				}

				return
			}

			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}

			if got != testCase.want {
				t.Errorf("mismatch:\ngot:\n%s\n\nwant:\n%s",
					got, testCase.want)
			}
		})
	}
}

func TestInjectBetweenMarkers_Idempotent(t *testing.T) {
	t.Parallel()

	content := `before
<!-- GEN:IDEM_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
existing generated content
<!-- GEN:IDEM_END -->
after`

	// Injecting the same replacement should produce identical output.
	result1, err := InjectBetweenMarkers(content, "IDEM", "existing generated content")
	if err != nil {
		t.Fatalf("first injection: %v", err)
	}

	result2, err := InjectBetweenMarkers(result1, "IDEM", "existing generated content")
	if err != nil {
		t.Fatalf("second injection: %v", err)
	}

	if result1 != result2 {
		t.Errorf("not idempotent:\nfirst:\n%s\n\nsecond:\n%s", result1, result2)
	}
}

func TestInjectFile(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	path := filepath.Join(dir, "test.md")

	content := `# Test
<!-- GEN:FILE_START -->
old
<!-- GEN:FILE_END -->
`

	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("writing test file: %v", err)
	}

	if err := InjectFile(path, "FILE", "new content"); err != nil {
		t.Fatalf("InjectFile: %v", err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading result: %v", err)
	}

	want := `# Test
<!-- GEN:FILE_START -->
<!-- DO NOT EDIT — auto-generated by make docs -->
new content
<!-- GEN:FILE_END -->
`

	if string(data) != want {
		t.Errorf("file content mismatch:\ngot:\n%s\nwant:\n%s", string(data), want)
	}
}

func TestInjectFile_NonexistentFile(t *testing.T) {
	t.Parallel()

	err := InjectFile("/nonexistent/path/file.md", "TEST", "content")
	if err == nil {
		t.Fatal("expected error for nonexistent file")
	}
}

// contains checks if s contains substr (simple helper to avoid importing strings in test).
func contains(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr || len(s) > 0 && containsAt(s, substr))
}

func containsAt(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}

	return false
}
